  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, achievement, or action to their own efforts, work, or advocacy, thereby seeking recognition or responsibility for the result.",
    "clarification": "Credit-claiming is identified when the senator uses first-person language (e.g., 'I secured,' 'I authored,' 'I announced,' 'I worked to') or explicitly ties a positive outcome to their personal involvement. This includes taking credit for legislative actions, securing funding, advocating for causes, or achieving policy goals. The focus is on the senator's direct or implied role in bringing about the outcome.",
    "positive_examples": [
